122	// Decode the --key-hex argument, emitting the shared key-format diagnostic
123	// (which never echoes the submitted key) on failure.
124	bool parseKey(std::string_view command, std::string_view usage,
125	              const std::string& keyHex, std::vector<unsigned char>& key) {
126	    if (decodeHex(keyHex, key)) {
127	        return true;
128	    }
129	    std::cerr << "messagetag " << command
