244	// Compare two fixed-length byte strings without leaking the length of any
245	// matching prefix: the loop always touches every byte and accumulates all
246	// differences, so the running time does not depend on where (or whether)
247	// the inputs differ.
248	bool constantTimeEqual(const unsigned char* a, const unsigned char* b,
249	                       std::size_t length) {
250	    unsigned char diff = 0;
251	    for (std::size_t i = 0; i < length; ++i) {
252	        diff |= static_cast<unsigned char>(a[i] ^ b[i]);
253	    }
254	    return diff == 0;
255	}
