257	int runVerify(int argc, char* argv[]) {
258	    // argv[1] is the "verify" subcommand name; parsing starts at argv[2].
259	    std::map<std::string, std::string> opts;
260	    if (!parseValueOptions(
261	            argc, argv, "verify", kVerifyUsage,
262	            std::vector<std::string_view>{"--key-hex", "--file", "--tag-hex"},
263	            opts)) {
264	        return 2;
265	    }
266	    if (!requireOption(opts, "verify", kVerifyUsage, "--key-hex") ||
267	        !requireOption(opts, "verify", kVerifyUsage, "--file") ||
268	        !requireOption(opts, "verify", kVerifyUsage, "--tag-hex")) {
269	        return 2;
270	    }
271	    const std::string& keyHex = opts["--key-hex"];
272	    const std::string& filePath = opts["--file"];
273	    const std::string& tagHex = opts["--tag-hex"];
274	
275	    // All input-format checks happen before the file is opened, so a
276	    // malformed key or tag is reported as a parameter error (exit 2) even
277	    // when the message file does not exist.
278	    std::vector<unsigned char> key;
279	    if (!parseKey("verify", kVerifyUsage, keyHex, key)) {
280	        return 2;
281	    }
282	
283	    // The supplied tag must decode to exactly 32 bytes (64 hex characters);
284	    // decodeHex already rejects empty input, odd length, non-hex characters
285	    // and whitespace, which also rules out a 0x prefix. The submitted tag is
286	    // deliberately not echoed back.
287	    std::vector<unsigned char> expected;
288	    if (!decodeHex(tagHex, expected) || expected.size() != kTagBytes) {
289	        std::cerr << "messagetag verify: error: invalid --tag-hex: expected "
290	                     "exactly 64 hexadecimal characters denoting 32 bytes "
291	                     "(0-9, a-f, A-F); empty, truncated or over-long values, "
292	                     "embedded whitespace and a 0x prefix are not accepted\n"
293	                  << kVerifyUsage;
294	        return 2;
295	    }
296	
297	    std::array<unsigned char, EVP_MAX_MD_SIZE> mac{};
298	    std::size_t macLength = 0;
299	    switch (hmacSha256File(key, filePath, mac, macLength)) {
300	        case HmacStatus::kReadError:
301	            // The partially read prefix must never be authenticated as if it
302	            // were the whole message.
303	            std::cerr << "messagetag verify: error: failed to read file: "
304	                      << filePath << "\n";
305	            return 1;
306	        case HmacStatus::kCryptoError:
307	            std::cerr << "messagetag verify: error: HMAC-SHA-256 "
308	                         "computation failed\n";
309	            return 1;
310	        case HmacStatus::kSuccess:
311	            break;
312	    }
313	
314	    if (macLength != kTagBytes ||
315	        !constantTimeEqual(mac.data(), expected.data(), kTagBytes)) {
316	        // State only that authentication failed; do not assign a cause (the
317	        // message, the key or the tag could each be the one that differs),
318	        // and never print the recomputed tag, a matched prefix or the key.
319	        std::cerr << "messagetag verify: error: authentication tag mismatch: "
320	                     "the supplied tag does not match the given key and file "
321	                     "content\n";
322	        return 3;
323	    }
324	
325	    std::cout << "OK\n";
326	    return 0;
327	}
328	
329	}  // namespace
330	
331	int main(int argc, char* argv[]) {
332	    if (argc == 2 && std::string_view(argv[1]) == "--version") {
333	        std::cout << "messagetag 0.1.0\n";
334	        return 0;
335	    }
336	    if (argc >= 2 && std::string_view(argv[1]) == "tag") {
337	        return runTag(argc, argv);
338	    }
339	    if (argc >= 2 && std::string_view(argv[1]) == "verify") {
340	        return runVerify(argc, argv);
341	    }
342	    std::cerr << "Usage: messagetag --version\n"
343	              << "       messagetag tag --key-hex <hex-key> "
344	                 "--file <message-file>\n"
345	              << "       messagetag verify --key-hex <hex-key> "
346	                 "--file <message-file> --tag-hex <hex-tag>\n";
347	    return 2;
348	}
